import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source for model_new_kernel
model_new_kernel_source = """
__global__ void model_new_kernel(const float* A, const float* B, float* C,
                                  int b, int i, int j, int L, int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < b * i * j * K) {
        float sum = 0.0f;
        for (int l_idx = 0; l_idx < L; ++l_idx) {
            // index in A: a_idx = b*(i*j*L) + i*(j*L) + j*L + l_idx
            int a_idx = b * (i * j * L) + i * (j * L) + j * L + l_idx;
            float a_val = A[a_idx];
            // B[l_idx][k] -> row = l_idx, col = k
            int b_row = l_idx; // because B's first dimension is l
            int c_col = k;
            float b_val = B[b_row * K + c_col];
            sum += a_val * b_val;
        }
        C[idx] = sum;
    }
}
"""

# Function source for model_new_cuda
model_new_cuda_source = """
torch::Tensor model_new_cuda(torch::Tensor A, torch::Tensor B) {
    int b = A.size(0);
    int i = A.size(1);
    int j = A.size(2);
    int l = A.size(3); // same as B's rows
    int k = B.size(1);

    float* A_ptr = A.data_ptr<float>();
    const float* B_ptr = B.data_ptr<float>();
    float* C_ptr = torch::empty(b, i, j, k, device=A.device()).data_ptr<float>(); // allocate output tensor

    int total_elements = b * i * j * k;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    model_new_kernel<<<num_blocks, block_size>>>(A_ptr, B_ptr, C_ptr, b, i, j, l, k);

    return torch::from_blob(C_ptr, {b,i,j,k}).to(A.device());
}
"""

# Compile the inline CUDA code for model_new_cuda
model_new_cuda = load_inline(
    name="model_new_cuda",
    cpp_sources=model_new_cuda_source,
    cuda_sources=model_new_kernel_source,
    functions=["model_new_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.model_new_cuda = model_new_cuda

    def forward(self, A, B):
        return self.model_new_cuda(A, B)
